'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8');const a=html.indexOf('/* Stage63: ability NAME-only'),b=html.indexOf('let pcInsanePreviewSheets=null',a);assert.ok(a>0&&b>a);const src=html.slice(a,b);const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[x]));const api=new Function('escapeHTML',src+'\nreturn {check:pcInsaneItemPreflight,render:pcInsaneItemPreflightHTML};')(escapeHTML);
const item=(v,ref='E32',state='changed',label='道具甲')=>({ref,label,value:v,state,usage:'使用',usageRef:'D32'}),supp=(...rows)=>({comparison:true,groups:{items:rows}});
test('Round212 only 3 known quantity coordinates, never usage flags',()=>{const r=api.check(supp(item('2'),item('4','E34'),item('0','E36')));assert.equal(r.length,3);assert.ok(r.every(x=>x.status==='数量来源待核对'));assert.equal(r[0].ref,'E32');assert.ok(r.every(x=>!Object.hasOwn(x,'usage')&&!Object.hasOwn(x,'usageRef')));});
test('Round212 formula, sample default, invalid and arbitrary free text remain read-only pending',()=>{const rows=[item('6','P40'),item('=2','E32','formula'),item('0','E32','unchanged'),item('-1'),item('123'),item('3.1')];assert.ok(api.check(supp(...rows)).every(x=>x.status==='待人工核对'));});
test('Round212 privacy and HTML escape',()=>{const out=api.render(api.check(supp(item('2','E32','changed','<img src=x onerror=1>'))));assert.match(out,/&lt;img/);assert.doesNotMatch(out,/<img src/);assert.doesNotMatch(out,/私人备注正文/);assert.doesNotMatch(src,/saveState\s*\(|pcWorkbookPut\s*\(|pcDraft\s*=/);});
test('Round212 no comparison means no quantity assumptions and CI retains the contract',()=>{assert.deepEqual(api.check({comparison:false,groups:{items:[item('2')]}}),[]);for(const n of ['pl-browser-synthetic.yml','pl-native-restore-gate.yml'])assert.match(fs.readFileSync(path.join(root,'.github/workflows',n),'utf8'),/round212-insane-item-count-preflight\.test\.cjs/);});
